package cn.minidayz.patcher;
import java.io.*;import java.util.*;import java.util.zip.*;import org.json.*;
/** Read-only APK structure inspection. Does not claim to recover source from native code. */
public final class ProjectAnalysis {
 static int le(byte[] b,int p){return (b[p]&255)|((b[p+1]&255)<<8)|((b[p+2]&255)<<16)|((b[p+3]&255)<<24);}
 public static JSONObject scan(File apk,FilesEx.Watch w)throws Exception{String sha=FilesEx.sha(apk,w);w.stage("project-scan","读取 APK 结构与可分析文件");ZipFile z=new ZipFile(apk);JSONArray dex=new JSONArray(),nativeLib=new JSONArray(),texts=new JSONArray();boolean il2cpp=false,metadata=false,mono=false;JSONObject meta=new JSONObject();int total=0;long expanded=0;try{Map<String,ZipEntry> entries=FilesEx.entries(z);for(ZipEntry e:entries.values()){FilesEx.check(w);total++;expanded+=e.getSize();String n=e.getName();if(n.matches("classes[0-9]*\\.dex")){InputStream in=z.getInputStream(e);byte[] header=new byte[112];int read=0;try{while(read<header.length){int k=in.read(header,read,header.length-read);if(k<0)break;read+=k;}}finally{in.close();}JSONObject item=new JSONObject().put("entry",n).put("size",e.getSize());if(read>=112&&header[0]=='d'&&header[1]=='e'&&header[2]=='x'){item.put("format","DEX").put("version",new String(header,4,3,"US-ASCII")).put("classes",le(header,96)).put("method_ids",le(header,88)).put("strings",le(header,56));}else item.put("warning","不支持的DEX头，仅记录文件");dex.put(item);}if(n.startsWith("lib/")&&n.endsWith(".so")){if(nativeLib.length()<160)nativeLib.put(new JSONObject().put("entry",n).put("size",e.getSize()));if(n.endsWith("/libil2cpp.so"))il2cpp=true;}if(n.endsWith("global-metadata.dat")){metadata=true;InputStream in=z.getInputStream(e);byte[] b=new byte[8];int read=0;try{while(read<8){int k=in.read(b,read,8-read);if(k<0)break;read+=k;}}finally{in.close();}meta.put("entry",n).put("size",e.getSize());if(read==8&&le(b,0)==0xfab11baf)meta.put("version",le(b,4));else meta.put("warning","元数据头未知或已变换");}if(n.endsWith("Assembly-CSharp.dll"))mono=true;if(AiWorkspace.allowed(n)&&e.getSize()<=196608&&texts.length()<100)texts.put(new JSONObject().put("entry",n).put("size",e.getSize()));w.progress(total,entries.size());}}finally{z.close();}String engine=il2cpp?"Unity IL2CPP":mono?"Unity Mono":"未确认";return new JSONObject().put("format","mdz-project-analysis/1").put("created_ms",System.currentTimeMillis()).put("input_sha256",sha).put("apk_size",apk.length()).put("entries",total).put("expanded_bytes",expanded).put("engine",engine).put("dex",dex).put("native_libraries",nativeLib).put("metadata",meta).put("metadata_found",metadata).put("text_candidates",texts).put("capabilities",new JSONObject().put("apk_structure",true).put("text_patch",true).put("java_decompiler",false).put("native_decompiler",false).put("automatic_native_migration",false)).put("limitations","当前为只读结构分析，尚未内置DEX到Java、IL2CPP反编译或原生代码自动迁移工具。");}
 public static JSONObject run(Jobs j)throws Exception{FilesEx.require(j.file(1).isFile(),"E_INPUT_MISSING: 请先导入游戏APK");JSONObject r=scan(j.file(1),j);j.stage("migration-evidence","核对新版关键组件指纹与元数据布局");r.put("migration_evidence",MigrationEvidence.scan(j.file(1),j));if(j.file(2).isFile()){try{JSONObject m=j.engine().module(j.file(2));r.put("module_name",m.optString("name")).put("module_version",m.optString("version")).put("module_sha256",FilesEx.sha(j.file(2),j));}catch(Exception e){r.put("module_error",e.getMessage());}}File tmp=new File(j.root,"project-analysis.pending");FilesEx.write(tmp,r.toString(2).getBytes("UTF-8"));FilesEx.atomic(tmp,new File(j.root,"project-analysis.json"));j.stage("project-analyzed","结构分析完成，可交给AI分析；不代表适配通过");return r;}
 public static String context(Jobs j)throws Exception{File f=new File(j.root,"project-analysis.json");if(!f.isFile()||!j.file(1).isFile())return "尚未生成当前APK结构分析。";JSONObject r=new JSONObject(new String(FilesEx.read(new FileInputStream(f),524288),"UTF-8"));if(!r.optString("input_sha256").equals(FilesEx.sha(j.file(1),j)))return "已导入不同APK，旧结构分析不参与本次请求，请重新分析。";return AiContext.compact("APK结构摘要：",r.toString(2),12000);}
 public static String display(JSONObject r){return "引擎："+r.optString("engine")+"\nAPK条目："+r.optInt("entries")+"\nDEX文件："+r.optJSONArray("dex").length()+"\n本地库："+r.optJSONArray("native_libraries").length()+"\n文本候选："+r.optJSONArray("text_candidates").length()+"\n\n"+r.optString("limitations")+"\n\n文件清单与头部信息：\n"+r.toString();}
}
